#!/usr/bin/env node
/**
 * poly-scout — Polymarket Smart Money Tracker
 * MCP skill for Claude
 *
 * Data sources:
 *   - https://data-api.polymarket.com/trades?market=<tokenId>&limit=N
 *   - https://data-api.polymarket.com/activity?user=<addr>&limit=N&type=TRADE
 *   - https://data-api.polymarket.com/positions?user=<addr>
 *   - https://gamma-api.polymarket.com/markets?limit=N&active=true&order=volume24hr&ascending=false
 */

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";
import Redis from "ioredis";

// ─── Config ──────────────────────────────────────────────────────────────────

const DATA_API = "https://data-api.polymarket.com";
const GAMMA_API = "https://gamma-api.polymarket.com";

const SMART_WALLET_TTL = 300;   // 5 min
const MARKET_TRADES_TTL = 60;   // 1 min
const POSITIONS_TTL = 120;      // 2 min

const redis = new Redis(process.env.REDIS_URL || "redis://localhost:6379", {
  lazyConnect: true,
  connectTimeout: 3000,
  maxRetriesPerRequest: 1,
  enableOfflineQueue: false,
});
redis.on("error", () => {}); // swallow — redis optional, graceful fallback

// ─── Types ───────────────────────────────────────────────────────────────────

interface GammaMkt {
  id: string;
  question: string;
  slug: string;
  active: boolean;
  volume24hr: number;
  clobTokenIds: string; // JSON-encoded string array
  endDate: string;
  resolved?: boolean;
}

interface DataTrade {
  proxyWallet: string;
  timestamp: number;
  conditionId: string;
  type: string;
  size: number;
  usdcSize: number;
  price: number;
  asset: string;
  side: string;
  outcomeIndex: number;
  title: string;
  slug: string;
  outcome: string;
  transactionHash: string;
}

interface DataPosition {
  proxyWallet: string;
  asset: string;
  conditionId: string;
  size: number;
  avgPrice: number;
  currentValue: number;
  cashPnl: number;
  percentPnl: number;
  totalBought: number;
  realizedPnl: number;
  curPrice: number;
  title: string;
  slug: string;
  outcome: string;
  endDate: string;
}

interface WalletStat {
  address: string;
  tradeCount: number;
  winRate: number;
  roi: number;
  totalUsdcTraded: number;
  openPositions: OpenPosition[];
}

interface OpenPosition {
  market_id: string;
  question: string;
  outcome: string;
  price: number;
  size_usdc: number;
  ts: number;
}

interface ConsensusSignal {
  market_id: string;
  question: string;
  direction: "YES" | "NO";
  confidence: number;
  smart_wallet_count: number;
}

// ─── Redis helpers ────────────────────────────────────────────────────────────

async function cacheGet(key: string): Promise<string | null> {
  try { return await redis.get(key); } catch { return null; }
}

async function cacheSet(key: string, value: string, ttl: number): Promise<void> {
  try { await redis.setex(key, ttl, value); } catch { /* ignore */ }
}

// ─── API helpers ──────────────────────────────────────────────────────────────

async function fetchJSON<T>(url: string): Promise<T> {
  const res = await fetch(url, {
    headers: { "User-Agent": "poly-scout/0.1.0" },
    signal: AbortSignal.timeout(15_000),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status} — ${url}`);
  return res.json() as Promise<T>;
}

function delay(ms: number) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// ─── Core data fetchers ───────────────────────────────────────────────────────

async function getTopMarkets(limit = 20): Promise<GammaMkt[]> {
  const cached = await cacheGet("poly-scout:top-markets");
  if (cached) return JSON.parse(cached);

  const markets = await fetchJSON<GammaMkt[]>(
    `${GAMMA_API}/markets?limit=${limit}&active=true&order=volume24hr&ascending=false`
  );
  await cacheSet("poly-scout:top-markets", JSON.stringify(markets), 120);
  return markets;
}

async function getMarketTradesRaw(tokenId: string, limit = 500): Promise<DataTrade[]> {
  const cacheKey = `poly-scout:trades:${tokenId}`;
  const cached = await cacheGet(cacheKey);
  if (cached) return JSON.parse(cached);

  const trades = await fetchJSON<DataTrade[]>(
    `${DATA_API}/trades?market=${tokenId}&limit=${limit}`
  );
  await cacheSet(cacheKey, JSON.stringify(trades), MARKET_TRADES_TTL);
  return trades;
}

async function getUserActivity(address: string, limit = 200): Promise<DataTrade[]> {
  const cacheKey = `poly-scout:activity:${address.toLowerCase()}`;
  const cached = await cacheGet(cacheKey);
  if (cached) return JSON.parse(cached);

  const acts = await fetchJSON<DataTrade[]>(
    `${DATA_API}/activity?user=${address}&limit=${limit}&type=TRADE`
  );
  await cacheSet(cacheKey, JSON.stringify(acts), POSITIONS_TTL);
  return acts;
}

async function getUserPositions(address: string): Promise<DataPosition[]> {
  const cacheKey = `poly-scout:positions:${address.toLowerCase()}`;
  const cached = await cacheGet(cacheKey);
  if (cached) return JSON.parse(cached);

  const pos = await fetchJSON<DataPosition[]>(
    `${DATA_API}/positions?user=${address}&sizeThreshold=0.01&limit=100`
  );
  await cacheSet(cacheKey, JSON.stringify(pos), POSITIONS_TTL);
  return pos;
}

// ─── Smart wallet scoring ─────────────────────────────────────────────────────

async function computeSmartWallets(): Promise<WalletStat[]> {
  const cached = await cacheGet("poly-scout:smart-wallets");
  if (cached) return JSON.parse(cached);

  // Step 1: pull trades from top 15 markets by volume
  const markets = await getTopMarkets(15);

  const walletTrades = new Map<string, DataTrade[]>();

  for (const mkt of markets) {
    let tokenIds: string[] = [];
    try { tokenIds = JSON.parse(mkt.clobTokenIds); } catch { continue; }

    const tokenId = tokenIds[0];
    if (!tokenId) continue;

    try {
      const trades = await getMarketTradesRaw(tokenId, 500);
      for (const t of trades) {
        const addr = t.proxyWallet.toLowerCase();
        if (!walletTrades.has(addr)) walletTrades.set(addr, []);
        walletTrades.get(addr)!.push(t);
      }
    } catch { /* skip failed market */ }

    await delay(80); // rate limit cushion
  }

  // Step 2: filter wallets with > 10 trades
  const qualified: WalletStat[] = [];

  for (const [address, trades] of walletTrades.entries()) {
    if (trades.length < 10) continue;

    // Basic scoring:
    // - tradeCount: raw count
    // - diversification: bets on multiple markets (not spammy)
    // - direction consistency: smart money backs different outcomes, not always same side
    // - ROI proxy: sum of (size * (1 - price)) for BUY — expected profit if correct

    const marketSet = new Set(trades.map(t => t.conditionId));
    if (marketSet.size < 3) continue; // must trade across 3+ markets

    const buyTrades = trades.filter(t => t.side === "BUY");
    const totalUsdcIn = buyTrades.reduce((s, t) => s + (t.usdcSize || 0), 0);
    if (totalUsdcIn < 50) continue; // must have skin in the game

    // Expected value proxy: sum of (shares * (1 - price)) where price is what they paid
    // If they bought YES at 0.3, expected profit per share if wins = 0.7 per USDC in
    const evProxy = buyTrades.reduce((s, t) => {
      return s + (t.usdcSize || 0) * (1 - t.price);
    }, 0);
    const roi = totalUsdcIn > 0 ? evProxy / totalUsdcIn : 0;

    // Direction diversity check: not just spamming same side
    const yesBuys = buyTrades.filter(t => t.outcomeIndex === 0).length;
    const noBuys = buyTrades.filter(t => t.outcomeIndex === 1).length;
    const totalBuys = buyTrades.length;
    const dirBias = Math.abs(yesBuys - noBuys) / Math.max(totalBuys, 1);
    if (dirBias > 0.9) continue; // skip wallets that only buy one outcome (bots)

    qualified.push({
      address,
      tradeCount: trades.length,
      winRate: roi,      // approximate — real win rate needs resolved market data
      roi,
      totalUsdcTraded: totalUsdcIn,
      openPositions: [],  // populated next
    });
  }

  // Sort by ROI proxy desc, take top 20
  qualified.sort((a, b) => b.roi - a.roi);
  const top = qualified.slice(0, 20);

  // Step 3: pull open positions for top wallets
  for (const wallet of top) {
    try {
      const positions = await getUserPositions(wallet.address);
      wallet.openPositions = positions
        .filter(p => p.size > 0.01 && p.curPrice > 0.01 && p.curPrice < 0.99)
        .map(p => ({
          market_id: p.conditionId,
          question: p.title,
          outcome: p.outcome,
          price: p.curPrice,
          size_usdc: p.currentValue,
          ts: 0,
        }));
    } catch { /* skip */ }
    await delay(100);
  }

  await cacheSet("poly-scout:smart-wallets", JSON.stringify(top), SMART_WALLET_TTL);
  return top;
}

// ─── MCP server setup ─────────────────────────────────────────────────────────

const server = new McpServer({
  name: "poly-scout",
  version: "0.1.0",
});

// ─── Tool: scan_smart_money ───────────────────────────────────────────────────

server.tool(
  "scan_smart_money",
  "Scan Polymarket for smart money wallets. Returns top wallets by consistent ROI across many markets, their open positions, and a consensus signal showing where smart money is concentrated. Results cached 5 min.",
  {},
  async () => {
    try {
      const wallets = await computeSmartWallets();

      // Build consensus: group open positions by market, count smart wallets per direction
      const consensusMap = new Map<string, { question: string; yes: number; no: number; wallets: Set<string> }>();

      for (const w of wallets) {
        for (const pos of w.openPositions) {
          const key = pos.market_id;
          if (!consensusMap.has(key)) {
            consensusMap.set(key, { question: pos.question, yes: 0, no: 0, wallets: new Set() });
          }
          const c = consensusMap.get(key)!;
          c.wallets.add(w.address);
          if (pos.outcome.toLowerCase() === "yes") c.yes++;
          else c.no++;
        }
      }

      const consensus: ConsensusSignal[] = [];
      for (const [market_id, data] of consensusMap.entries()) {
        if (data.wallets.size < 2) continue;
        const total = data.yes + data.no;
        const yesRatio = total > 0 ? data.yes / total : 0.5;
        const direction = yesRatio >= 0.5 ? "YES" : "NO";
        const confidence = Math.abs(yesRatio - 0.5) * 2;

        consensus.push({
          market_id,
          question: data.question,
          direction,
          confidence: Math.round(confidence * 100) / 100,
          smart_wallet_count: data.wallets.size,
        });
      }

      consensus.sort((a, b) => b.confidence - a.confidence);

      const output = {
        wallets: wallets.map(w => ({
          address: w.address,
          trade_count: w.tradeCount,
          roi_proxy: Math.round(w.roi * 1000) / 1000,
          total_usdc_traded: Math.round(w.totalUsdcTraded),
          open_positions: w.openPositions.slice(0, 10),
        })),
        consensus: consensus.slice(0, 20),
        scanned_at: new Date().toISOString(),
      };

      return {
        content: [{ type: "text", text: JSON.stringify(output, null, 2) }],
      };
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      return { content: [{ type: "text", text: `Error: ${msg}` }], isError: true };
    }
  }
);

// ─── Tool: get_wallet_positions ───────────────────────────────────────────────

server.tool(
  "get_wallet_positions",
  "Get all current open positions for a specific Polymarket wallet address. Returns market questions, outcomes, entry prices, and current P&L.",
  { address: z.string().describe("Polygon wallet address (0x...)") },
  async ({ address }) => {
    try {
      const [positions, activity] = await Promise.all([
        getUserPositions(address),
        getUserActivity(address, 50),
      ]);

      const openPos = positions
        .filter(p => p.size > 0.01)
        .map(p => ({
          market_id: p.conditionId,
          question: p.title,
          outcome: p.outcome,
          entry_price: p.avgPrice,
          cur_price: p.curPrice,
          size_usdc: Math.round(p.currentValue * 100) / 100,
          cash_pnl: Math.round(p.cashPnl * 100) / 100,
          pct_pnl: Math.round(p.percentPnl * 100) / 100,
          end_date: p.endDate,
        }))
        .sort((a, b) => Math.abs(b.size_usdc) - Math.abs(a.size_usdc));

      const recentTrades = activity.slice(0, 10).map(t => ({
        question: t.title,
        outcome: t.outcome,
        side: t.side,
        price: t.price,
        usdc: t.usdcSize,
        ts: new Date(t.timestamp * 1000).toISOString(),
      }));

      const output = {
        address: address.toLowerCase(),
        open_positions: openPos,
        recent_trades: recentTrades,
        fetched_at: new Date().toISOString(),
      };

      return {
        content: [{ type: "text", text: JSON.stringify(output, null, 2) }],
      };
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      return { content: [{ type: "text", text: `Error: ${msg}` }], isError: true };
    }
  }
);

// ─── Tool: get_late_money ─────────────────────────────────────────────────────

server.tool(
  "get_late_money",
  "Detect unusual position buildup in last 48-72h for a specific Polymarket market. Identifies volume spikes vs baseline, net direction, and wallet concentration. Use the conditionId from gamma-api markets.",
  {
    market_id: z.string().describe("Market conditionId (0x...) from gamma-api, or token ID"),
    token_id: z.string().optional().describe("CLOB token ID if known (from clobTokenIds field of the market)"),
  },
  async ({ market_id, token_id }) => {
    try {
      // Resolve token_id from gamma if not provided
      let tokenId = token_id;
      let question = "";

      if (!tokenId) {
        // Try gamma to find the market
        try {
          const markets = await fetchJSON<GammaMkt[]>(
            `${GAMMA_API}/markets?conditionIds=${market_id}&limit=1`
          );
          if (markets.length > 0) {
            const ids = JSON.parse(markets[0].clobTokenIds);
            tokenId = ids[0];
            question = markets[0].question;
          }
        } catch { /* ignore */ }
      }

      if (!tokenId) {
        return {
          content: [{ type: "text", text: `Could not resolve token_id for market ${market_id}. Provide token_id directly.` }],
          isError: true,
        };
      }

      // Fetch 500 most recent trades
      const trades = await getMarketTradesRaw(tokenId, 500);

      const now = Math.floor(Date.now() / 1000);
      const h48 = now - 48 * 3600;
      const h120 = now - 120 * 3600; // 5-day baseline window

      const recent = trades.filter(t => t.timestamp >= h48);
      const baseline = trades.filter(t => t.timestamp >= h120 && t.timestamp < h48);

      // Volume: USDC traded
      const recentVol = recent.reduce((s, t) => s + (t.usdcSize || t.size * t.price || 0), 0);
      const baselineVol = baseline.reduce((s, t) => s + (t.usdcSize || t.size * t.price || 0), 0);
      // Normalize baseline to 48h equivalent
      const baselineNorm = (baselineVol / 72) * 48;
      const volRatio = baselineNorm > 0 ? recentVol / baselineNorm : recentVol > 0 ? 999 : 0;

      // Net direction
      const recentBuys = recent.filter(t => t.side === "BUY");
      const yesBuys = recentBuys.filter(t => t.outcomeIndex === 0);
      const noBuys = recentBuys.filter(t => t.outcomeIndex === 1);
      const yesVol = yesBuys.reduce((s, t) => s + (t.usdcSize || 0), 0);
      const noVol = noBuys.reduce((s, t) => s + (t.usdcSize || 0), 0);
      const totalDirectional = yesVol + noVol;

      let signal: "YES" | "NO" | "NEUTRAL" = "NEUTRAL";
      let confidence = 0;
      if (totalDirectional > 0) {
        const yesRatio = yesVol / totalDirectional;
        if (yesRatio > 0.6) { signal = "YES"; confidence = (yesRatio - 0.5) * 2; }
        else if (yesRatio < 0.4) { signal = "NO"; confidence = (0.5 - yesRatio) * 2; }
      }

      // Wallet concentration — top 5 wallets by recent USDC
      const walletMap = new Map<string, number>();
      for (const t of recent) {
        const addr = t.proxyWallet.toLowerCase();
        walletMap.set(addr, (walletMap.get(addr) || 0) + (t.usdcSize || 0));
      }
      const sorted = [...walletMap.entries()].sort((a, b) => b[1] - a[1]);
      const topWallets = sorted.slice(0, 5).map(([addr]) => addr);

      const output = {
        market_id,
        token_id: tokenId,
        question: question || market_id,
        signal,
        confidence: Math.round(confidence * 100) / 100,
        volume_48h_usdc: Math.round(recentVol),
        volume_48h_vs_baseline: Math.round(volRatio * 100) / 100,
        yes_usdc_48h: Math.round(yesVol),
        no_usdc_48h: Math.round(noVol),
        unique_wallets_48h: walletMap.size,
        top_wallets: topWallets,
        trade_count_48h: recent.length,
        analyzed_at: new Date().toISOString(),
      };

      return {
        content: [{ type: "text", text: JSON.stringify(output, null, 2) }],
      };
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      return { content: [{ type: "text", text: `Error: ${msg}` }], isError: true };
    }
  }
);

// ─── Tool: get_market_trades ──────────────────────────────────────────────────

server.tool(
  "get_market_trades",
  "Raw trade feed for a Polymarket market — last N trades with wallet addresses, prices, sides, and sizes. Pass the CLOB token ID (from clobTokenIds field of gamma markets).",
  {
    token_id: z.string().describe("CLOB token ID from the market (found in clobTokenIds field of gamma-api response)"),
    limit: z.number().optional().default(100).describe("Number of trades to return (max 500)"),
  },
  async ({ token_id, limit }) => {
    try {
      const safeLimit = Math.min(limit ?? 100, 500);
      const trades = await getMarketTradesRaw(token_id, safeLimit);

      const formatted = trades.slice(0, safeLimit).map(t => ({
        wallet: t.proxyWallet.toLowerCase(),
        side: t.side,
        outcome: t.outcome,
        outcome_index: t.outcomeIndex,
        price: t.price,
        size_shares: t.size,
        usdc: t.usdcSize,
        question: t.title,
        slug: t.slug,
        ts: new Date(t.timestamp * 1000).toISOString(),
        tx: t.transactionHash,
      }));

      const output = {
        token_id,
        trade_count: formatted.length,
        trades: formatted,
        fetched_at: new Date().toISOString(),
      };

      return {
        content: [{ type: "text", text: JSON.stringify(output, null, 2) }],
      };
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      return { content: [{ type: "text", text: `Error: ${msg}` }], isError: true };
    }
  }
);

// ─── Start ────────────────────────────────────────────────────────────────────

const transport = new StdioServerTransport();
await server.connect(transport);
